UPDATE quest_set SET title = 'Compose 기본 명령과 필드: up -d, -p·-f, down -v, stop·start, restart, build·pull, ps -a, config, port (2/2)', description = 'docker compose 의 기본 명령과 옵션의 동작을 한 개념씩 반복합니다. -p 로 프로젝트 이름을, -f 로 다른 파일을 지정하는 것, down 과 down -v 의 볼륨 차이, stop 과 start 가 컨테이너를 지우지 않는 것과 ps -a, restart 가 서비스를 다시 시작하는 것, config --services 로 서비스 이름만 보는 것, port 로 포트 연결을 확인하는 것, build 와 pull 의 대상, Dockerfile 을 고친 뒤 up -d --build 가 필요한 것을 짧은 객관식·빈칸·순서 문제로 익히고, 올리고 내리기, Dockerfile 고치고 반영하기, 멈췄다 다시 시작하기, 볼륨 데이터 남기고 내렸다 올리기의 순서를 연습합니다.' WHERE id = 253 AND title = 'Compose 기본 명령과 필드: up -d, -p·-f, down -v, stop·start, build·pull, ports, restart, ADD 와 COPY (2/2)';
-- 세트 255: 문제 14개는 빈칸 10개·순서 4개뿐이며 -q, 125~127, kill, exec -e, -i 파이프는 묻지 않음
UPDATE quest_set SET title = '컨테이너 상태와 종료 코드: ps --filter, 종료 코드, wait, rename, pause·unpause, logs --tail·-t, exec -w, --rm, prune (2/2)', description = '컨테이너 상태를 읽고 다루는 기본 동작을 한 개념씩 반복합니다. docker ps 의 --filter 를 여러 번 쓸 때의 조건, 컨테이너 안 명령의 종료 코드와 STATUS 의 Exited, wait 의 동작, rename 과 이름 충돌, pause 한 컨테이너의 Paused 상태와 exec 오류, logs 의 --tail 과 -t, exec 의 -w, --rm, system df 의 열, container prune 의 확인과 -f 를 짧은 빈칸·순서 문제로 익히고, 종료 코드 확인하기, 멈추고 다시 이어서 실행, 로그 줄여 보기, 정지한 컨테이너 정리의 순서를 연습합니다.' WHERE id = 255 AND title = '컨테이너 상태와 종료 코드: ps -q·--filter, 125·126·127, wait, rename, pause, stop·kill, logs, exec -w·-e, prune (2/2)';
